function toast(s){const t=q('#mlToast');t.textContent=s;t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove('show'),1900)}
function visual(scene){
 if(scene.kind==='causation')return `<div class="ml-visual-card ml-causation-card"><div class="ml-cause-example"><span>CONCRETE EXAMPLE</span><strong>Older fish may be both longer and heavier.</strong><p>Age could help explain why Length and Weight rise together—even if changing length by itself would not cause a fixed weight gain.</p></div><div class="ml-cause-compare"><article class="observed"><div><b>✓</b><span>THE DATA SHOWS</span></div><strong>Longer fish tend to weigh more.</strong><small>An upward association appears in these 159 observations.</small></article><div class="ml-cause-arrow" aria-hidden="true">≠</div><article class="causal"><div><b>×</b><span>THE DATA DOES NOT SHOW</span></div><strong>Length alone causes weight gain.</strong><small>No experiment changed fish length while holding other factors constant.</small></article></div><div class="ml-third-factors"><strong>Other possible influences</strong><span>Age</span><span>Species</span><span>Nutrition</span><span>Environment</span></div>${scene.definition?`<div class="ml-definition"><strong>${esc(scene.definition.term)}:</strong> ${esc(scene.definition.text)}</div>`:''}</div>`
 if(scene.kind==='evidence')return `<div class="ml-visual-card ml-evidence-card"><div class="ml-evidence-question"><span>WHAT DOES THE CHART SUPPORT?</span><strong>Move from observation → evidence → careful claim</strong></div><div class="ml-evidence-grid"><div class="ml-evidence-chart"><div class="ml-mini-chart-label">Observed data</div><svg viewBox="0 0 260 160" role="img" aria-label="Small scatterplot with an upward pattern and visible variation"><path d="M25 12V138H245" class="ml-mini-axis"/><path d="M30 132 C95 120 157 84 235 25" class="ml-mini-trend"/>${[[38,128],[49,124],[58,119],[71,116],[78,106],[91,110],[103,93],[110,101],[121,85],[132,76],[140,82],[151,62],[160,73],[171,53],[184,60],[192,38],[205,45],[220,22],[229,31]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" class="${i===11||i===15?'ml-mini-var':''}"/>`).join('')}</svg><div class="ml-evidence-observations"><span>↗ Overall upward pattern</span><span>↕ Points still vary</span></div></div><div class="ml-evidence-claims"><article class="ml-claim supported"><div><span>SUPPORTED</span><b>✓</b></div><p>“Longer fish <strong>in this dataset</strong> tend to weigh more.”</p><small>Describes the observed association and limits the claim to the sample.</small></article><article class="ml-claim unsupported"><div><span>NOT SUPPORTED</span><b>×</b></div><p>“Making a fish longer <strong>causes</strong> it to gain a predictable amount of weight.”</p><small>Claims cause and certainty that the chart did not test.</small></article></div></div><div class="ml-evidence-rule"><b>A defensible claim</b><span>describes the pattern</span><i>+</i><span>names the dataset</span><i>+</i><span>avoids claiming cause</span></div>${scene.definition?`<div class="ml-definition"><strong>${esc(scene.definition.term)}:</strong> ${esc(scene.definition.text)}</div>`:''}</div>`
 if(scene.kind==='scatterplot'){const pts=[[9,7,2],[10,8,2],[11,10,2],[13,20,2],[13,40,0],[16,70,1],[18,85,1],[19,110,0],[20,120,1],[20,145,0],[22,160,1],[22,200,0],[24,242,5],[24,300,3],[25,270,0],[26,300,1],[27,390,5],[27,500,5],[29,475,5],[29,600,5],[31,650,5],[32,720,5],[33,800,6],[35,430,4],[35,920,5],[37,850,1],[37,1000,6],[40,500,4],[40,1000,1],[43,567,4],[45,770,4],[48,950,4],[52,1250,4],[56,1550,4],[59,1650,4]],colors=['#3f7f58','#3b82b4','#e7a526','#8b63b6','#d05b76','#e47732','#6b8795'],names=['Roach','Perch','Smelt','Parkki','Pike','Bream','Whitefish'];return `<div class="ml-visual-card ml-scatter-card"><div class="ml-scatter-head"><div><span>LENGTH × WEIGHT</span><strong>Every dot represents one observed fish</strong></div><div class="ml-scatter-legend">${names.map((n,i)=>`<span><i style="background:${colors[i]}"></i>${n}</span>`).join('')}</div></div><div class="ml-scatter-layout"><div class="ml-scatter-y">Weight (grams)</div><div class="ml-scatter-plot" role="img" aria-label="Scatterplot of fish length and weight. Points trend upward from short light fish to long heavy fish, with variation among fish of similar lengths."><div class="ml-scatter-grid" aria-hidden="true">${[1500,1000,500,0].map(v=>`<span>${v}</span>`).join('')}</div><svg viewBox="0 0 600 230" preserveAspectRatio="none" aria-hidden="true"><path class="ml-scatter-trend" d="M20 211 C175 194 315 139 575 18"/>${pts.map(([x,y,c])=>`<circle cx="${20+(x-7)/54*555}" cy="${214-y/1700*196}" r="4.2" fill="${colors[c]}"/>`).join('')}</svg><div class="ml-scatter-callout trend-note"><b>Overall upward pattern</b><span>Longer fish tend to weigh more</span></div><div class="ml-scatter-callout variation-note"><b>Variation remains</b><span>Similar length, different weight</span></div></div><div class="ml-scatter-x"><span>10</span><span>20</span><span>30</span><span>40</span><span>50</span><span>60</span><b>Length (cm) →</b></div></div><div class="ml-scatter-reading"><span><b>One dot</b> = one fish</span><span><b>Upward cloud</b> = positive association</span><span><b>Vertical gaps</b> = the pattern is not exact</span></div>${scene.definition?`<div class="ml-definition"><strong>${esc(scene.definition.term)}:</strong> ${esc(scene.definition.text)}</div>`:''}</div>`}
 if(scene.kind==='dataset-intro')return `<div class="ml-visual-card ml-dataset-intro"><h3>${esc(scene.visualTitle||scene.title)}</h3><p>${esc(scene.visualText||scene.copy)}</p><div class="ml-dataset-stage" aria-label="Colorful fish swim into a database table and become saved rows"><div class="ml-water-shine" aria-hidden="true"></div><div class="ml-bubbles" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i style="--bubble-size:${5+(i%4)*3}px;--bubble-time:${4+(i%4)*.8}s;--bubble-delay:${i*-.55}s;--bubble-x:${7+(i*17)%88}%"></i>`).join('')}</div><div class="ml-fish-stream" aria-hidden="true">${scene.species.map((name,i)=>`<span class="ml-fish-token" style="--fish-delay:${i*.48}s;--fish-color:${scene.colors[i]};--lane-top:${42+(i%5)*45}px;--curve:${(i%3-1)*10}px;--dive:${70-(i%5)*45}px"><i class="ml-fish-tail"></i><i class="ml-fish-body"><b></b><em>${esc(name)}</em></i></span>`).join('')}</div><div class="ml-database"><div class="ml-db-sign"><span>DATABASE</span><strong>Fish Table</strong></div><div class="ml-db-slot"><i></i></div><div class="ml-db-table" aria-hidden="true"><div class="ml-db-header"><b>fish</b><b>species</b><b>size</b></div>${Array.from({length:7},(_,i)=>`<div class="ml-db-row" style="--row-delay:${1.15+i*.48}s"><b>🐟</b><span></span><span></span></div>`).join('')}</div><div class="ml-db-glow" aria-hidden="true"></div></div><div class="ml-seabed" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><div class="ml-swim-caption"><strong>Swim in → become a row!</strong><span>Each fish observation gets a home in the table.</span></div></div></div>`;
 if(scene.kind==='features-target')return `<div class="ml-visual-card ml-role-card"><div class="ml-role-question"><span>QUESTION</span><strong>Can these measurements help estimate this fish’s weight?</strong></div><div class="ml-role-example" aria-label="A worked fish row showing input features and target"><div class="ml-role-fish"><span aria-hidden="true">🐟</span><strong>Fish #1</strong><small>Roach</small></div><div class="ml-role-inputs"><div class="ml-role-label"><b>X</b><span>INPUTS WE KNOW</span></div><div class="ml-role-values"><div><small>Length</small><strong>19.0 cm</strong></div><div><small>Height</small><strong>6.48 cm</strong></div><div><small>Width</small><strong>3.35 cm</strong></div></div></div><div class="ml-role-arrow" aria-hidden="true"><span>use to estimate</span><b>→</b></div><div class="ml-role-target"><div class="ml-role-label"><b>y</b><span>ANSWER TO LEARN</span></div><small>Weight</small><strong>27.0 g</strong></div></div><div class="ml-role-note"><strong>Species is context, not the target in this question.</strong><span>If the question changed to “Which species is this?”, then Species would become the target.</span></div>${scene.definition?`<div class="ml-definition"><strong>${esc(scene.definition.term)}:</strong> ${esc(scene.definition.text)}</div>`:''}</div>`;
 if(scene.kind==='histogram'){const bars=[51,28,24,18,13,10,8,3,2,2,0,0,0,0,0,1];return `<div class="ml-visual-card ml-hist-card"><div class="ml-hist-head"><div><span>WEIGHT DISTRIBUTION</span><strong>159 fish grouped into 100 g ranges</strong></div><div class="ml-hist-key"><i></i> One bar = one weight range</div></div><div class="ml-hist-layout"><div class="ml-hist-y">Number of fish</div><div class="ml-hist-plot" role="img" aria-label="Histogram of fish weights. Most fish are in the lightest weight ranges, counts decline as weight increases, and one fish appears in the heaviest range."><div class="ml-hist-grid" aria-hidden="true"><span>50</span><span>40</span><span>30</span><span>20</span><span>10</span><span>0</span></div><div class="ml-hist-bars" aria-hidden="true">${bars.map((v,i)=>`<i style="--bar:${v}" class="${i===0?'peak':''} ${i===bars.length-1?'outlier':''}"><b>${v||''}</b></i>`).join('')}</div><div class="ml-hist-callout peak-note"><b>Most common range</b><span>0–100 g</span></div><div class="ml-hist-callout tail-note"><b>Long right tail</b><span>Fewer heavy fish</span></div><div class="ml-hist-callout outlier-note"><b>Possible outlier</b><span>1,600–1,700 g</span></div></div><div class="ml-hist-x"><span>0</span><span>400</span><span>800</span><span>1,200</span><span>1,600</span><b>Weight (grams) →</b></div></div><div class="ml-hist-reading"><span><b>Bar height</b> = number of fish</span><span><b>Bar position</b> = weight range</span><span><b>Overall shape</b> = right-skewed</span></div>${scene.definition?`<div class="ml-definition"><strong>${esc(scene.definition.term)}:</strong> ${esc(scene.definition.text)}</div>`:''}</div>`}
 const nodes=(scene.nodes||[]).map((n,i)=>`<div class="ml-flow-node"><b>${esc(n.icon||i+1)}</b>${esc(n.label||n)}</div>${i<(scene.nodes||[]).length-1?'<div class="ml-flow-arrow">→</div>':''}`).join('');
 const table=scene.table?`<div class="ml-data-grid-wrap"><table class="ml-data-grid"><thead><tr><th class="ml-row-number">#</th>${scene.table.columns.map(c=>`<th><span>${esc(c.name)}</span><small>${esc(c.type)}</small></th>`).join('')}</tr></thead><tbody>${scene.table.rows.map((row,i)=>`<tr><th class="ml-row-number">${i+1}</th>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="ml-table-status"><span><strong>${esc(scene.table.total)}</strong> rows</span><span><strong>${scene.table.columns.length}</strong> columns</span><span><i></i> Embedded Fish.csv preview</span></div>`:'';
 return `<div class="ml-visual-card ${table?'ml-table-card':''}"><h3>${esc(scene.visualTitle||scene.title)}</h3><p>${esc(scene.visualText||scene.copy)}</p>${table}${nodes?`<div class="ml-flow">${nodes}</div>`:''}${scene.definition?`<div class="ml-definition"><strong>${esc(scene.definition.term)}:</strong> ${esc(scene.definition.text)}</div>`:''}</div>`;
}
function renderScene(){const s=C.scenes[state.scene],steps=q('#sceneNav');steps.innerHTML=C.scenes.map((x,i)=>`<button class="ml-scene-step ${i===state.scene?'active':''} ${i<state.scene?'done':''}" data-index="${i+1}" data-scene="${i}" ${i>state.unlocked?'disabled':''}>${esc(x.short||x.title)}</button>`).join('');qa('[data-scene]',steps).forEach(b=>b.onclick=()=>{state.scene=+b.dataset.scene;renderScene();store()});q('#sceneKicker').textContent=`Learn · Scene ${state.scene+1}`;q('#sceneTitle').textContent=s.title;q('#sceneCopy').textContent=s.copy;q('#sceneCount').textContent=`Scene ${state.scene+1} of ${C.scenes.length}`;q('#sceneProgress').style.width=`${(state.scene+1)/C.scenes.length*100}%`;q('#sceneVisual').innerHTML=visual(s);q('#sceneBack').disabled=state.scene===0;q('#sceneNext').textContent=state.scene===C.scenes.length-1?'Open notebook →':'Next →';q('#instructorCue').textContent=s.cue||C.instructorCue;}
function setMode(mode){state.mode=mode;qa('.ml-mode').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));qa('[data-view]').forEach(v=>v.hidden=v.dataset.view!==mode);q('#modeProgress').textContent={learn:'Build the mental model',notebook:`${state.completed.size} of ${C.cells.length} code cells complete`,explore:C.explore?.tasks?'Complete 3 evidence tasks':'Change one thing and observe',challenge:'Explain what the model can and cannot claim'}[mode];if(mode==='explore')renderExplore();if(mode==='challenge')renderChallenge();store()}
function normalize(code){return code.replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/\s+/g,' ').trim().toLowerCase()}
function pythonError(cell,code){if(/[“”‘’]/.test(code))return ['SyntaxError: invalid character in identifier','Python uses straight quotation marks. Replace the curved quotes highlighted by your word processor.'];const opens=(code.match(/\(/g)||[]).length,closes=(code.match(/\)/g)||[]).length;if(opens!==closes)return ['SyntaxError: unexpected EOF while parsing','One or more parentheses are not closed. Count each opening and closing parenthesis.'];if(!code.trim())return ['NameError: this cell has no code','Type the requested Python statements before running the cell.'];if(/\b(panda|seaborns|sklearnn)\b/i.test(code))return ["ModuleNotFoundError: check the library name",'The simulator recognizes pandas, seaborn, and sklearn when they are spelled exactly.'];return null}
function evaluate(cell,index){const code=cell.querySelector('.ml-code').value,output=cell.querySelector('.ml-output'),spec=C.cells[index],basic=pythonError(cell,code);state.executions++;cell.querySelector('.ml-exec').textContent=`In [${state.executions}]:`;cell.classList.remove('error','success');if(basic)return fail(cell,output,basic[0],basic[1],index);const n=normalize(code),requirements=spec.requires||[],missingIndexes=requirements.map((r,i)=>new RegExp(r,'i').test(n)?-1:i).filter(i=>i>=0);if(missingIndexes.length){const missingNames=missingIndexes.map(i=>spec.requireLabels?.[i]).filter(Boolean),detail=missingNames.length?` Still needed: ${missingNames.join(', ')}.`:'';return fail(cell,output,spec.error||'NameError: required step not found',(spec.coach||'Check the task above the cell and make sure every requested operation appears.')+detail,index)}cell.classList.add('success');state.completed.add(index);output.innerHTML=renderOutput(spec.output,index,code);updateMetrics(index);q('#modeProgress').textContent=`${state.completed.size} of ${C.cells.length} code cells complete`;store();return true}
function fail(cell,out,error,coach,index){cell.classList.add('error');out.innerHTML=`<span class="ml-error">${esc(error)}</span><span class="ml-coach"><strong>Coach:</strong> ${esc(coach)} <button class="ml-btn" data-inline-hint="${index}" type="button">Show a hint</button></span>`;q('[data-inline-hint]',out).onclick=()=>showHint(index);store();return false}
function renderOutput(o,index,code){if(typeof o==='function')o=o(state,code);if(!o)o='Cell ran successfully.';const cell=q(`[data-cell="${index}"]`);if(cell)updateChecklist(cell,index);return esc(o).replace(/\n/g,'<br>')+`<span class="ml-coach" style="background:var(--ml-green-soft);color:var(--ml-green-dark)"><strong>Success:</strong> ${esc(C.cells[index].success||'The visual workspace has been updated.')}</span>`}
function showHint(index){state.hints.add(index);const cell=q(`[data-cell="${index}"]`),out=q('.ml-output',cell),spec=C.cells[index];out.insertAdjacentHTML('beforeend',`<span class="ml-hint"><strong>Hint:</strong> ${esc(spec.hint)}</span>`);store()}
function updateMetrics(index){if(index<0)return;const spec=C.cells[index],cell=q(`[data-cell="${index}"]`),result=q('.ml-inline-result',cell),metricGrid=q('[data-cell-metrics]',cell),chart=q('[data-cell-chart]',cell),hasMetrics=!!spec.metrics,hasChart=!!spec.visual;if(!hasMetrics&&!hasChart){result.hidden=true;return}result.hidden=false;metricGrid.hidden=!hasMetrics;metricGrid.innerHTML=hasMetrics?Object.entries(spec.metrics).map(([k,v])=>`<div class="ml-metric"><b>${esc(v)}</b><span>${esc(k)}</span></div>`).join(''):'';chart.hidden=!hasChart;if(hasChart){if(C.id==='data_detective'&&index===3)renderFishHistogram(chart);else if(C.id==='data_detective'&&index===4)renderFishBarplot(chart);else if(C.id==='data_detective'&&index===5)renderFishScatter(chart);else renderMiniChart(index,chart)}}
function renderFishHistogram(target){const bins=[66,30,18,19,14,8,1,1,2],xTicks=[0,400,800,1200,1600],yTicks=[0,20,40,60],sx=x=>60+x/1800*600,sy=y=>250-y/70*220;target.innerHTML=`<svg viewBox="0 0 700 300" role="img" aria-label="Histogram showing the distribution of Weight in grams for 159 fish"><rect x="60" y="30" width="600" height="220" fill="#fff"/>${yTicks.map(v=>`<line x1="60" y1="${sy(v)}" x2="660" y2="${sy(v)}" stroke="#dfe7e2"/><text x="51" y="${sy(v)+4}" text-anchor="end" font-size="10" fill="#61716b">${v}</text>`).join('')}${xTicks.map(v=>`<line x1="${sx(v)}" y1="30" x2="${sx(v)}" y2="250" stroke="#edf2ef"/><text x="${sx(v)}" y="266" text-anchor="middle" font-size="10" fill="#61716b">${v}</text>`).join('')}<line x1="60" y1="250" x2="660" y2="250" stroke="#61716b"/><line x1="60" y1="30" x2="60" y2="250" stroke="#61716b"/>${bins.map((count,i)=>{const x=sx(i*200)+3,w=sx(200)-sx(0)-6,y=sy(count);return `<rect x="${x}" y="${y}" width="${w}" height="${250-y}" rx="2" fill="#3977a8" fill-opacity=".86"><title>${i*200}–${(i+1)*200} g: ${count} fish</title></rect>`}).join('')}<text x="360" y="294" text-anchor="middle" font-size="12" font-weight="700" fill="#17322a">Weight (g)</text><text x="15" y="140" text-anchor="middle" font-size="12" font-weight="700" fill="#17322a" transform="rotate(-90 15 140)">Count of fish</text></svg>`}
